// 假设这是你的图像数据（只需模拟数据）
const imageData = [
  {x: 10, y: 10},
  {x: 20, y: 20},
  {x: 30, y: 30},
  // ... 模拟数据
  {x: 100, y: 100},
];

// 计算蓝色圆点数量
let blueCircleCount = 0;
imageData.forEach(point => {
  if (point.x === 50 && point.y === 50) {
    ++blueCircleCount;
  }
});

// 输出结果
console.log(`{"count": ${blueCircleCount}}`);
```

